-- ============================================================================
-- SEED MASTER KELAS, WALI KELAS, 83 SISWA & JADWAL SESI (CBT SRT 68 V3.9)
-- Jalankan di Supabase -> SQL Editor -> New Query -> Run
-- ============================================================================

-- 1. Master Kelas & Wali Kelas (8 Kelas)
ON CONFLICT (id_kelas) DO UPDATE SET nama_kelas = EXCLUDED.nama_kelas, wali_kelas_username = EXCLUDED.wali_kelas_username, wali_kelas_name = EXCLUDED.wali_kelas_name, keterangan = EXCLUDED.keterangan;

-- 2. Akun Wali Kelas (8 Akun) & Siswa (83 Akun)
ON CONFLICT (username) DO UPDATE SET password = EXCLUDED.password, name = EXCLUDED.name, role = EXCLUDED.role, kelas = EXCLUDED.kelas, id_kelas = EXCLUDED.id_kelas, sesi = EXCLUDED.sesi, ruang = EXCLUDED.ruang;

-- 3. Jadwal Sesi Ujian (30 Nov - 4 Des 2026)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, exam_date = EXCLUDED.exam_date, exam_day = EXCLUDED.exam_day, start_time = EXCLUDED.start_time, end_time = EXCLUDED.end_time, kelas_akses = EXCLUDED.kelas_akses;